  sessionId: string;
  data?: EventData;
  revenue?: number;
}>): Promise<void> {
  try {
    await db.analyticsEvent.createMany({
      data: events.map((e) => ({
        shop: e.shop,
        quizId: e.quizId,
        eventType: e.eventType,
        sessionId: e.sessionId,
        data: JSON.stringify(e.data ?? {}),
        revenue: e.revenue ?? 0,
      })),
      skipDuplicates: true,
    });
  } catch (error) {
    console.error("Batch event tracking failed:", error);
  }
}
```

