## PUBLIC API ERROR BOUNDARY (Storefront Widget)

```typescript
// For the storefront widget JS — vanilla error handling:
// extensions/quiz-widget/assets/quiz-widget.js

window.addEventListener("error", function(event) {
  // Don't break the merchant's storefront on widget errors
  console.error("[QuizSnap] Widget error:", event.error);

  // Hide broken widget gracefully
  const container = document.querySelector("[data-quiz-slug]");
  if (container) {
    container.innerHTML = "";  // Clear broken state silently
  }
});

window.addEventListener("unhandledrejection", function(event) {
  console.error("[QuizSnap] Unhandled promise:", event.reason);
  event.preventDefault();  // Don't bubble to merchant page error handlers
});
```

