type QuizStatus = "draft" | "active" | "paused" | "archived";

function getStatusBadgeTone(status: QuizStatus): "success" | "warning" | "critical" | undefined {
  const toneMap = {
    active: "success" as const,
    paused: "warning" as const,
    archived: "critical" as const,
    draft: undefined,
  };
  return toneMap[status];
}

