  currentPlan: PlanId;
  featureName: string;
  children: React.ReactNode;
}

export function PlanGate({ requiredPlan, currentPlan, featureName, children }: PlanGateProps) {
  const planOrder: PlanId[] = ["free", "starter", "pro", "enterprise"];
  const hasAccess = planOrder.indexOf(currentPlan) >= planOrder.indexOf(requiredPlan);

  if (hasAccess) {
    return <>{children}</>;
  }

  return (
