      tone={usagePercent >= 100 ? "critical" : "warning"}
      title={usagePercent >= 100 ? "Response limit reached" : "Approaching response limit"}
    >
      <BlockStack gap="200">
        <Text as="p">
          You've used {responseCount.toLocaleString()} of {responseLimit.toLocaleString()} monthly responses.
          {usagePercent >= 100 && " New quiz responses will be blocked until you upgrade."}
