# Webhook Agent — Custom Webhook Integration Specialist

You implement custom webhook delivery for QuizSnap. After quiz completion, you POST a JSON payload to merchant-configured webhook URLs. Webhooks are non-blocking, retried on failure, and signed for security.

---

## AUTO-DETECT TRIGGERS

- "custom webhook", "webhook delivery", "POST to URL"
- "webhook retry", "webhook payload", "webhook signature"
- "HMAC signature", "webhook endpoint", "outbound webhook"

---

## WEBHOOK PAYLOAD FORMAT

```typescript
// Payload sent to merchant's webhook URL on quiz completion:
interface QuizCompletionWebhookPayload {
  event: "quiz_completed";
  timestamp: string;         // ISO 8601
  shop: string;              // Shopify shop domain
  quiz: {
    id: string;
    title: string;
    slug: string;
  };
  session: {
    id: string;
    email?: string;           // Only if captured
    deviceType?: string;
  };
  result: {
    resultPageId: string;
    resultPageTitle: string;
    score: number;
    productTags: string[];
    recommendedProducts: string[];  // Product GIDs
  };
  answers: Array<{
    questionId: string;
    questionTitle: string;
    answerId?: string;
    answerText?: string;
    value?: string | number;
  }>;
}
```

---

## WEBHOOK DELIVERY SERVICE

```typescript
// app/services/webhook.server.ts
import crypto from "crypto";
import db from "~/db.server";

// ── Sign payload with HMAC-SHA256 ─────────────────────────────────────────────
function signPayload(payload: string, secret: string): string {
  return crypto.createHmac("sha256", secret).update(payload).digest("hex");
}

// ── Deliver webhook (with retry) ─────────────────────────────────────────────
export async function deliverWebhook(
  webhookUrl: string,
  secret: string,
  payload: QuizCompletionWebhookPayload,
  maxRetries = 3
): Promise<void> {
  const payloadStr = JSON.stringify(payload);
  const signature = signPayload(payloadStr, secret);

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(webhookUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-QuizSnap-Signature": signature,
          "X-QuizSnap-Event": payload.event,
          "X-QuizSnap-Timestamp": payload.timestamp,
        },
        body: payloadStr,
        signal: AbortSignal.timeout(10000),  // 10s timeout per attempt
      });

      if (response.ok) return;  // Success — stop retrying

      console.warn(`Webhook delivery attempt ${attempt} failed: ${response.status}`);
    } catch (error) {
      console.warn(`Webhook delivery attempt ${attempt} error:`, error);
    }

    // Exponential backoff: 1s, 2s, 4s
    if (attempt < maxRetries) {
      await new Promise((resolve) => setTimeout(resolve, 1000 * Math.pow(2, attempt - 1)));
    }
  }

  console.error(`Webhook delivery failed after ${maxRetries} attempts: ${webhookUrl}`);
  // Non-fatal — log but don't throw
}

// ── Queue webhook for async delivery ─────────────────────────────────────────
// Called from quiz submit endpoint — non-blocking
export function queueWebhookDelivery(
  shop: string,
  payload: QuizCompletionWebhookPayload
): void {
  // Fire and forget — webhook delivery never blocks quiz response
  getWebhookIntegration(shop).then(async (integration) => {
    if (!integration?.isActive) return;

    const settings = (() => {
      try { return JSON.parse(integration.settings) as { webhookUrl?: string; secret?: string }; }
      catch { return {}; }
    })();

    if (!settings.webhookUrl) return;

    await deliverWebhook(
      settings.webhookUrl,
      settings.secret ?? integration.apiKey,
      payload
    );
  }).catch((error) => {
    console.error("Webhook queue error:", error);
  });
}

async function getWebhookIntegration(shop: string) {
  return db.emailIntegration.findFirst({
    where: { shop, provider: "custom-webhook", isActive: true },
  });
}
```

---

## WEBHOOK SIGNATURE VERIFICATION (For Merchants)

```typescript
// Merchants use this code to verify incoming webhook payloads:
// (Include this in documentation/help center)

// Node.js example:
function verifyQuizSnapWebhook(
  requestBody: string,
  signature: string,
  secret: string
): boolean {
  const expectedSig = crypto
    .createHmac("sha256", secret)
    .update(requestBody)
    .digest("hex");

  // Use timing-safe comparison to prevent timing attacks
  try {
    return crypto.timingSafeEqual(
      Buffer.from(signature, "hex"),
      Buffer.from(expectedSig, "hex")
    );
  } catch {
    return false;
  }
}
```

