// Used in quiz builder to search and select products for result pages
export async function searchProducts(
  shop: string,
  query: string,
  options: {
    tags?: string[];
    collections?: string[];
    limit?: number;
    includeArchived?: boolean;
  } = {}
): Promise<Array<{
  id: string;
  productGid: string;
  title: string;
  imageUrl: string | null;
  tags: string[];
  priceMin: number | null;
  priceMax: number | null;
}>> {
  const { tags, collections, limit = 20, includeArchived = false } = options;

  const products = await db.productMapping.findMany({
    where: {
      shop,
      status: includeArchived ? undefined : "active",
      title: query ? { contains: query, mode: "insensitive" } : undefined,
    },
    orderBy: { title: "asc" },
    take: limit,
    select: {
      id: true,
      productGid: true,
      title: true,
      imageUrl: true,
      tags: true,
      priceMin: true,
      priceMax: true,
      collections: true,
    },
  });

  // Filter by tags if specified (post-query, since tags stored as JSON)
  return products
    .map((p) => ({
      ...p,
      tags: (() => {
        try { return JSON.parse(p.tags) as string[]; }
        catch { return []; }
      })(),
    }))
    .filter((p) => {
      if (tags && tags.length > 0) {
        return tags.some((tag) => p.tags.includes(tag));
      }
      return true;
    });
}
