export default function MyQuizzes() {
  const navigate = useNavigate();
  const shopify = useAppBridge();

  const [modalOpen, setModalOpen] = useState(false);
  const [showAIOverlay, setShowAIOverlay] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
  const [showEmptyState] = useState(false); // Toggle to true to see empty state

  const handleOpenModal = useCallback(() => {
    setModalOpen(true);
  }, []);

  const handleCloseModal = useCallback(() => {
    setModalOpen(false);
  }, []);

  const handleSelectTemplate = useCallback(
    (templateId: string) => {
      setSelectedTemplate(templateId);
      setModalOpen(false);

      if (templateId === "blank") {
        navigate("/app/quizzes/new");
      } else {
        setShowAIOverlay(true);
      }
    },
    [navigate],
  );

  const handleAIComplete = useCallback(() => {
    setShowAIOverlay(false);
    shopify.toast.show("Quiz created successfully!");
    navigate(`/app/quizzes/new?template=${selectedTemplate}`);
  }, [navigate, selectedTemplate, shopify]);

  const handleEditQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}`);
    },
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}/preview`);
    },
    [navigate],
  );

