function ProductMappingTab({
  questions,
  onAddProduct,
  onRemoveProduct,
}: {
  questions: Question[];
  onAddProduct: (questionId: string, optionId: string, product: string) => void;
  onRemoveProduct: (questionId: string, optionId: string, product: string) => void;
}) {
  const [browseValue, setBrowseValue] = useState<Record<string, string>>({});

  return (
    <BlockStack gap="600">
      {questions.map((question) => (
        <Card key={question.id}>
          <BlockStack gap="400">
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              {question.title}
            </Text>
            <Divider />
            <BlockStack gap="400">
              {question.options.map((option) => {
                const fieldKey = `${question.id}-${option.id}`;
                return (
                  <BlockStack key={option.id} gap="200">
                    <Text as="p" variant="bodyMd" fontWeight="medium">
                      {option.label}
                    </Text>
                    <InlineStack gap="200" blockAlign="end">
                      <div style={{ flex: 1 }}>
                        <TextField
                          label=""
                          labelHidden
                          value={browseValue[fieldKey] || ""}
                          onChange={(value) =>
                            setBrowseValue((prev) => ({
                              ...prev,
                              [fieldKey]: value,
                            }))
                          }
                          autoComplete="off"
                          placeholder="Search products..."
                        />
                      </div>
                      <Button
                        onClick={() => {
                          const value = browseValue[fieldKey];
                          if (value && value.trim()) {
                            onAddProduct(question.id, option.id, value.trim());
                            setBrowseValue((prev) => ({
                              ...prev,
                              [fieldKey]: "",
                            }));
                          }
                        }}
                      >
                        Browse products
                      </Button>
                    </InlineStack>
                    {option.products.length > 0 && (
                      <InlineStack gap="200">
                        {option.products.map((product) => (
                          <Tag
                            key={product}
                            onRemove={() =>
                              onRemoveProduct(question.id, option.id, product)
                            }
                          >
                            {product}
                          </Tag>
                        ))}
                      </InlineStack>
                    )}
                  </BlockStack>
                );
              })}
            </BlockStack>
          </BlockStack>
        </Card>
      ))}
    </BlockStack>
  );
}

