      },
    },
  };

  const response = await fetch("https://a.klaviyo.com/api/profile-subscription-bulk-create-jobs/", {
    method: "POST",
    headers: { "Authorization": `Klaviyo-API-Key ${apiKey}`, "Content-Type": "application/json", "revision": "2024-10-15" },
    body: JSON.stringify(payload),
    signal: AbortSignal.timeout(10000),
  });

  if (!response.ok) {
    throw new Error(`Klaviyo API error: ${response.status}`);
  }
}

async function syncToMailchimp(apiKey: string, serverPrefix: string, audienceId: string, email: string, quizData: { quizTitle: string; quizSlug: string; resultPageTitle: string }) {
  const crypto = await import("crypto");
  const emailHash = crypto.createHash("md5").update(email.toLowerCase()).digest("hex");
  const memberData = {
    email_address: email,
    status_if_new: "subscribed",
    tags: [`quiz-${quizData.quizSlug}`, `result-${quizData.resultPageTitle.toLowerCase().replace(/\s+/g, "-")}`],
  };

  const response = await fetch(
    `https://${serverPrefix}.api.mailchimp.com/3.0/lists/${audienceId}/members/${emailHash}`,
    {
      method: "PUT",
      headers: { "Authorization": `Bearer ${apiKey}`, "Content-Type": "application/json" },
      body: JSON.stringify(memberData),
      signal: AbortSignal.timeout(10000),
    }
  );

  if (!response.ok) {
    throw new Error(`Mailchimp API error: ${response.status}`);
  }
}

